SELECT cs.post_id AS postId, cs.category_id AS categoryId, c.category_name AS categoryName, cs.title AS title, cs.content AS content, cs.views AS views, cs.created_at AS createdAt, cs.author_id AS authorId, cs.city AS city, cs.district AS district, (SELECT COUNT(*) FROM comments_cinesquare cc WHERE cc.post_id = cs.post_id) AS commentCount FROM cinesquare cs JOIN category c ON cs.category_id = c.category_id
cs.category_id = #{categoryId}
AND cs.post_id < #{lastPostId}
ORDER BY ${orderBy}, cs.post_id DESC LIMIT #{limit}

SELECT cs.post_id AS postId, cs.category_id AS categoryId, c.category_name AS categoryName, cs.title AS title, cs.content AS content, cs.views AS views, cs.created_at AS createdAt, cs.author_id AS authorId, cs.city AS city, cs.district AS district, cs.like_count AS likeCount FROM cinesquare cs JOIN category c ON cs.category_id = c.category_id
WHERE cs.created_at BETWEEN #{startDate} AND #{endDate}
ORDER BY cs.like_count DESC, cs.post_id DESC LIMIT #{limit}

